// N1 direct-connect authentication and connection-setting validation. No LiteNetLib / UnityEngine references:
// compiled into the plugin, the launcher and the offline tests. C# 5.
//
// Join code: 25 Crockford base32 characters (23 random = 115 bits from the OS CSPRNG, 2 check characters that only
// catch typos), shown as XXXXX-XXXXX-XXXXX-XXXXX-XXXXX. The code is generated by the launcher per Host launch, handed
// to the game through the process environment (never the command line, never a file, never a log) and only its derived
// HMAC key is kept in memory by the plugin.
//
// Handshake (both directions authenticated, challenge-response, replay-safe):
//   client -> host  connection request: Hello { ..., ClientNonce[16] }
//   host  -> client AuthChallenge { ServerNonce[16] }            (fresh per accepted connection, single use)
//   client -> host  AuthResponse  { HMAC(key, "client" transcript) }
//   host  -> client Welcome { ..., HostProof = HMAC(key, "host" transcript) }
// transcript = protocol version, game version, host instance id, client instance id, client nonce, server nonce.
// The transport (LiteNetLib UDP) is NOT encrypted: this proves both sides know the join code and prevents strangers
// from joining; it does not hide gameplay traffic from someone who can watch the packets.
using System;
using System.Collections.Generic;
using System.Net;
using System.Security.Cryptography;
using System.Text;

namespace TS2MP.Shared
{
    public static class JoinAuth
    {
        public const string EnvVar = "TS2MP_JOIN_CODE";     // process environment of the started game only
        public const int CodeChars = 25, RandomChars = 23, NonceBytes = 16, ProofBytes = 32;
        const string Alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"; // Crockford base32 (no I, L, O, U)

        public static string NewCode()
        {
            var raw = new byte[RandomChars];
            using (var rng = RandomNumberGenerator.Create()) rng.GetBytes(raw);
            var sb = new StringBuilder(CodeChars);
            for (int i = 0; i < RandomChars; i++) sb.Append(Alphabet[raw[i] & 31]); // 256 % 32 == 0: no modulo bias
            Array.Clear(raw, 0, raw.Length);
            string body = sb.ToString();
            return body + Check(body);
        }

        static string Check(string body)
        {
            using (var h = SHA256.Create())
            {
                var d = h.ComputeHash(Encoding.ASCII.GetBytes("TS2MP-code-check:" + body));
                return new string(new[] { Alphabet[d[0] & 31], Alphabet[d[1] & 31] });
            }
        }

        // Accepts lower case, spaces and dashes, O->0, I/L->1. Returns null if the input is not a valid code.
        public static string Normalize(string input)
        {
            if (input == null) return null;
            var sb = new StringBuilder(CodeChars);
            foreach (char c0 in input)
            {
                char c = char.ToUpperInvariant(c0);
                if (c == '-' || c == ' ' || c == '\t') continue;
                if (c == 'O') c = '0';
                else if (c == 'I' || c == 'L') c = '1';
                if (Alphabet.IndexOf(c) < 0) return null;
                sb.Append(c);
                if (sb.Length > CodeChars) return null;
            }
            if (sb.Length != CodeChars) return null;
            string s = sb.ToString();
            return Check(s.Substring(0, RandomChars)) == s.Substring(RandomChars) ? s : null;
        }

        public static string Format(string normalized)
        {
            if (normalized == null || normalized.Length != CodeChars) return normalized;
            return normalized.Substring(0, 5) + "-" + normalized.Substring(5, 5) + "-" + normalized.Substring(10, 5) + "-" + normalized.Substring(15, 5) + "-" + normalized.Substring(20, 5);
        }

        // 115-bit random input: a plain domain-separated hash is an adequate KDF (no password stretching needed).
        public static byte[] DeriveKey(string normalizedCode)
        {
            if (normalizedCode == null) throw new ArgumentNullException("normalizedCode");
            using (var h = SHA256.Create()) return h.ComputeHash(Encoding.ASCII.GetBytes("TS2MP-N1-join-key:" + normalizedCode));
        }

        public static byte[] NewNonce()
        {
            var n = new byte[NonceBytes];
            using (var rng = RandomNumberGenerator.Create()) rng.GetBytes(n);
            return n;
        }

        public static byte[] Proof(byte[] key, bool hostSide, int protocol, string gameVersion, string hostInstance, string clientInstance, byte[] clientNonce, byte[] serverNonce)
        {
            var buf = new List<byte>(160);
            AddStr(buf, hostSide ? "TS2MP-N1-host-proof" : "TS2MP-N1-client-proof");
            buf.AddRange(BitConverter.GetBytes(protocol));
            AddStr(buf, gameVersion ?? "");
            AddStr(buf, hostInstance ?? "");
            AddStr(buf, clientInstance ?? "");
            buf.AddRange(clientNonce);
            buf.AddRange(serverNonce);
            using (var mac = new HMACSHA256(key)) return mac.ComputeHash(buf.ToArray());
        }

        static void AddStr(List<byte> buf, string s)
        {
            var b = Encoding.UTF8.GetBytes(s);
            buf.AddRange(BitConverter.GetBytes(b.Length));
            buf.AddRange(b);
        }

        public static bool FixedTimeEquals(byte[] a, byte[] b)
        {
            if (a == null || b == null || a.Length != b.Length) return false;
            int diff = 0;
            for (int i = 0; i < a.Length; i++) diff |= a[i] ^ b[i];
            return diff == 0;
        }
    }

    // Validation of user-entered connection settings (launcher + plugin share the rules).
    public static class NetConfig
    {
        public const int DefaultPort = 27960;

        public static bool ValidPort(int port) { return port >= 1024 && port <= 65535; }

        public static bool TryParsePort(string s, out int port)
        {
            port = 0;
            if (s == null) return false;
            s = s.Trim();
            return s.Length > 0 && s.Length <= 5 && int.TryParse(s, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out port) && ValidPort(port);
        }

        // Host listen address: an IPv4 literal (0.0.0.0 = all interfaces). No names, no IPv6.
        public static bool ValidBindAddress(string s)
        {
            IPAddress ip;
            return IsIPv4Literal(s) && IPAddress.TryParse(s, out ip) && !IsMulticastOrBroadcast(ip);
        }

        // Client target: IPv4 literal or DNS name (RFC 1123 labels). Not 0.0.0.0, broadcast or multicast.
        public static bool ValidConnectAddress(string s)
        {
            if (string.IsNullOrEmpty(s) || s.Length > 253) return false;
            if (IsIPv4Literal(s))
            {
                IPAddress ip;
                return IPAddress.TryParse(s, out ip) && !ip.Equals(IPAddress.Any) && !IsMulticastOrBroadcast(ip);
            }
            if (s.IndexOf(':') >= 0) return false;   // IPv6 / host:port not supported
            bool allDigitsAndDots = true;
            foreach (char c in s) if (!(char.IsDigit(c) || c == '.')) { allDigitsAndDots = false; break; }
            if (allDigitsAndDots) return false;      // malformed dotted number such as 1.2.3 or 999.1.1.1
            string name = s.EndsWith(".") ? s.Substring(0, s.Length - 1) : s;
            foreach (var label in name.Split('.'))
            {
                if (label.Length < 1 || label.Length > 63 || label[0] == '-' || label[label.Length - 1] == '-') return false;
                foreach (char c in label)
                    if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-')) return false;
            }
            return true;
        }

        public static bool IsIPv4Literal(string s)
        {
            if (string.IsNullOrEmpty(s)) return false;
            var parts = s.Split('.');
            if (parts.Length != 4) return false;
            foreach (var p in parts)
            {
                int v;
                if (p.Length < 1 || p.Length > 3 || !int.TryParse(p, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out v) || v > 255) return false;
                if (p.Length > 1 && p[0] == '0') return false; // no octal-looking forms
            }
            return true;
        }

        public static bool IsLoopback(string s)
        {
            IPAddress ip;
            return IsIPv4Literal(s) && IPAddress.TryParse(s, out ip) && IPAddress.IsLoopback(ip);
        }

        static bool IsMulticastOrBroadcast(IPAddress ip)
        {
            var b = ip.GetAddressBytes();
            return b.Length == 4 && (b[0] >= 224 || (b[0] == 255 && b[1] == 255 && b[2] == 255 && b[3] == 255));
        }
    }

    // Host-side abuse limits for connection attempts and failed authentications. Not thread-safe: used from the
    // LiteNetLib event callbacks, which SessionNode raises on the thread calling Tick().
    public sealed class AuthLimiter
    {
        public int RequestsPerWindow = 20;          // connection requests per IP per RequestWindowMs
        public long RequestWindowMs = 10000;
        public int FailuresBeforeBlock = 5;         // failed auths per IP within FailureWindowMs
        public long FailureWindowMs = 60000;
        public long BlockMs = 120000;
        public int GlobalFailuresBeforeLock = 30;   // failed auths from all IPs within GlobalWindowMs
        public long GlobalWindowMs = 600000;
        public long GlobalLockMs = 60000;
        public int MaxTrackedAddresses = 1024;

        readonly Func<long> _now;
        readonly Dictionary<string, Entry> _byIp = new Dictionary<string, Entry>();
        readonly Queue<long> _globalFailures = new Queue<long>();
        long _globalLockUntil;

        sealed class Entry { public long ReqWindowStart; public int Requests; public readonly Queue<long> Failures = new Queue<long>(); public long BlockedUntil; public long LastSeen; }

        public AuthLimiter(Func<long> nowMs) { _now = nowMs; }

        public int TrackedAddresses { get { return _byIp.Count; } }
        public bool GlobalLocked { get { return _now() < _globalLockUntil; } }

        // Called for every connection request. False = refuse (blocked, too many requests, or global lock).
        public bool AllowRequest(string ip, out string why)
        {
            long now = _now();
            why = null;
            if (now < _globalLockUntil) { why = "global auth lock (" + (_globalLockUntil - now) / 1000 + " s left)"; return false; }
            var e = Get(ip, now);
            if (now < e.BlockedUntil) { why = "address blocked after failed join codes (" + (e.BlockedUntil - now) / 1000 + " s left)"; return false; }
            if (now - e.ReqWindowStart >= RequestWindowMs) { e.ReqWindowStart = now; e.Requests = 0; }
            if (++e.Requests > RequestsPerWindow) { why = "too many connection requests"; return false; }
            return true;
        }

        public void Failure(string ip)
        {
            long now = _now();
            var e = Get(ip, now);
            e.Failures.Enqueue(now);
            while (e.Failures.Count > 0 && now - e.Failures.Peek() > FailureWindowMs) e.Failures.Dequeue();
            if (e.Failures.Count >= FailuresBeforeBlock) { e.BlockedUntil = now + BlockMs; e.Failures.Clear(); }
            _globalFailures.Enqueue(now);
            while (_globalFailures.Count > 0 && now - _globalFailures.Peek() > GlobalWindowMs) _globalFailures.Dequeue();
            if (_globalFailures.Count >= GlobalFailuresBeforeLock) { _globalLockUntil = now + GlobalLockMs; _globalFailures.Clear(); }
        }

        public void Success(string ip)
        {
            Entry e;
            if (_byIp.TryGetValue(ip, out e)) e.Failures.Clear();
        }

        Entry Get(string ip, long now)
        {
            Entry e;
            if (_byIp.TryGetValue(ip, out e)) { e.LastSeen = now; return e; }
            if (_byIp.Count >= MaxTrackedAddresses) Prune(now);
            e = new Entry { ReqWindowStart = now, LastSeen = now };
            _byIp[ip] = e;
            return e;
        }

        void Prune(long now)
        {
            var drop = new List<string>();
            foreach (var kv in _byIp)
                if (now >= kv.Value.BlockedUntil && now - kv.Value.LastSeen > Math.Max(FailureWindowMs, RequestWindowMs)) drop.Add(kv.Key);
            foreach (var k in drop) _byIp.Remove(k);
            if (_byIp.Count >= MaxTrackedAddresses)
            {
                // Still full of active entries: drop the stalest non-blocked one so the table stays bounded.
                string oldest = null; long t = long.MaxValue;
                foreach (var kv in _byIp) if (now >= kv.Value.BlockedUntil && kv.Value.LastSeen < t) { t = kv.Value.LastSeen; oldest = kv.Key; }
                if (oldest != null) _byIp.Remove(oldest);
            }
        }
    }

    // Bounded memory of recently used client nonces (a replayed Hello is rejected even before the challenge).
    public sealed class NonceCache
    {
        readonly int _cap;
        readonly HashSet<string> _set = new HashSet<string>();
        readonly Queue<string> _order = new Queue<string>();
        public NonceCache(int capacity) { _cap = capacity; }

        // False if the nonce was seen before.
        public bool Add(byte[] nonce)
        {
            string k = Convert.ToBase64String(nonce);
            if (_set.Contains(k)) return false;
            _set.Add(k); _order.Enqueue(k);
            while (_order.Count > _cap) _set.Remove(_order.Dequeue());
            return true;
        }
    }
}
